.ds-button-subtle {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: relative;
  height: 1.5rem;
  min-width: 1.5rem;
  padding: 0 0.5rem;
  border: 0;
  border-radius: var(--radii-sm, 0.25rem);
  background: color-mix(in oklab, var(--colors-gray-3, #f0f0f0) 80%, transparent);
  color: var(--colors-gray-text, #202020);
  font-family: var(--fonts-body, var(--font-inter, Inter)), sans-serif;
  font-size: 0.75rem;
  font-weight: 600;
  line-height: 1.125rem;
  white-space: nowrap;
  cursor: pointer;
  transition: background 200ms cubic-bezier(0.2, 0.0, 0, 1.0), border-color 200ms cubic-bezier(0.2, 0.0, 0, 1.0), color 200ms cubic-bezier(0.2, 0.0, 0, 1.0);
}

.ds-button-subtle:hover:not(:disabled) {
  background: var(--colors-gray-4, #e8e8e8);
  color: var(--colors-gray-text, #202020);
}

.ds-button-subtle:focus-visible {
  outline: 2px solid var(--colors-gray-text, #202020);
  outline-offset: 2px;
}

.ds-button-subtle:disabled {
  background: var(--colors-background-control-disabled, #f9f9f9);
  color: var(--colors-text-disabled, #bbbbbb);
  cursor: not-allowed;
}

@media (prefers-reduced-motion: reduce) {
  .ds-button-subtle {
    transition: none;
  }
}

.ds-button-solid {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: relative;
  height: 1.5rem;
  min-width: 1.5rem;
  padding: 0 0.5rem;
  border: 0;
  border-radius: var(--radii-sm, 0.25rem);
  background: var(--colors-accent-solid, hsl(156.99deg 51% 54.1%));
  color: var(--colors-accent-solid-foreground, #303030);
  font-family: var(--fonts-body, var(--font-inter, Inter)), sans-serif;
  font-size: 0.75rem;
  font-weight: 600;
  line-height: 1.125rem;
  white-space: nowrap;
  cursor: pointer;
  transition: background 200ms cubic-bezier(0.2, 0.0, 0, 1.0), border-color 200ms cubic-bezier(0.2, 0.0, 0, 1.0), color 200ms cubic-bezier(0.2, 0.0, 0, 1.0);
}

.ds-button-solid:hover:not(:disabled) {
  background: var(--colors-accent-solid, hsl(156.99deg 51% 54.1%));
  color: var(--colors-accent-solid-foreground, #303030);
  outline: 1px solid color-mix(in oklab, var(--colors-accent-solid-foreground, #303030) 20%, transparent);
  outline-offset: -1px;
}

.ds-button-solid:focus-visible {
  outline: 2px solid var(--colors-accent-text, hsl(156.99deg 45% 35%));
  outline-offset: 2px;
}

.ds-button-solid:disabled {
  background: var(--colors-background-control-disabled, #f9f9f9);
  color: var(--colors-text-disabled, #bbbbbb);
  cursor: not-allowed;
}

@media (prefers-reduced-motion: reduce) {
  .ds-button-solid {
    transition: none;
  }
}

.ds-button-outline {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: relative;
  height: 1.5rem;
  min-width: 1.5rem;
  padding: 0 0.5rem;
  border: 1px solid var(--colors-gray-7, #cecece);
  border-radius: var(--radii-sm, 0.25rem);
  background: var(--colors-background-control, #fcfcfc);
  color: var(--colors-gray-text, #202020);
  font-family: var(--fonts-body, var(--font-inter, Inter)), sans-serif;
  font-size: 0.75rem;
  font-weight: 600;
  line-height: 1.125rem;
  white-space: nowrap;
  cursor: pointer;
  transition: background 200ms cubic-bezier(0.2, 0.0, 0, 1.0), border-color 200ms cubic-bezier(0.2, 0.0, 0, 1.0), color 200ms cubic-bezier(0.2, 0.0, 0, 1.0);
}

.ds-button-outline:hover:not(:disabled) {
  background: var(--colors-gray-3, #f0f0f0);
  color: var(--colors-gray-text, #202020);
  border-color: var(--colors-gray-8, #bbbbbb);
}

.ds-button-outline:focus-visible {
  outline: 2px solid var(--colors-gray-text, #202020);
  outline-offset: 2px;
}

.ds-button-outline:disabled {
  background: var(--colors-background-control-disabled, #f9f9f9);
  color: var(--colors-text-disabled, #bbbbbb);
  cursor: not-allowed;
}

@media (prefers-reduced-motion: reduce) {
  .ds-button-outline {
    transition: none;
  }
}

.ds-button-ghost {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: relative;
  height: 1.5rem;
  min-width: 1.5rem;
  padding: 0 0.5rem;
  border: 0;
  border-radius: var(--radii-sm, 0.25rem);
  background: transparent;
  color: var(--colors-text-muted, #646464);
  font-family: var(--fonts-body, var(--font-inter, Inter)), sans-serif;
  font-size: 0.75rem;
  font-weight: 600;
  line-height: 1.125rem;
  white-space: nowrap;
  cursor: pointer;
  transition: background 200ms cubic-bezier(0.2, 0.0, 0, 1.0), border-color 200ms cubic-bezier(0.2, 0.0, 0, 1.0), color 200ms cubic-bezier(0.2, 0.0, 0, 1.0);
}

.ds-button-ghost:hover:not(:disabled) {
  background: var(--colors-accent-3, hsl(156.99deg 90% 96.3%));
  color: var(--colors-accent-text, hsl(156.99deg 45% 35%));
}

.ds-button-ghost:focus-visible {
  outline: 2px solid var(--colors-accent-text, hsl(156.99deg 45% 35%));
  outline-offset: 2px;
}

.ds-button-ghost:disabled {
  background: transparent;
  color: var(--colors-text-disabled, #bbbbbb);
  cursor: not-allowed;
}

@media (prefers-reduced-motion: reduce) {
  .ds-button-ghost {
    transition: none;
  }
}

.ds-button-plain {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: relative;
  height: auto;
  min-width: 0;
  padding: 0;
  border: 0;
  border-radius: var(--radii-sm, 0.25rem);
  background: transparent;
  color: var(--colors-text-muted, #646464);
  font-family: var(--fonts-body, var(--font-inter, Inter)), sans-serif;
  font-size: 0.75rem;
  font-weight: 600;
  line-height: 1.125rem;
  white-space: nowrap;
  cursor: pointer;
  transition: background 200ms cubic-bezier(0.2, 0.0, 0, 1.0), border-color 200ms cubic-bezier(0.2, 0.0, 0, 1.0), color 200ms cubic-bezier(0.2, 0.0, 0, 1.0);
}

.ds-button-plain:hover:not(:disabled) {
  background: transparent;
  color: var(--colors-text-default, #202020);
}

.ds-button-plain:focus-visible {
  outline: 2px solid var(--colors-border-default, #e0e0e0);
  outline-offset: 2px;
}

.ds-button-plain:disabled {
  background: transparent;
  color: var(--colors-text-disabled, #bbbbbb);
  cursor: not-allowed;
}

.ds-button-plain::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 1.5rem;
  height: 1.5rem;
  transform: translate(-50%, -50%);
}

@media (prefers-reduced-motion: reduce) {
  .ds-button-plain {
    transition: none;
  }
}

.ds-input {
  box-sizing: border-box;
  appearance: none;
  width: 100%;
  height: 1.5rem;
  padding: 0 0.5rem;
  border: 1px solid var(--colors-border-default, #e0e0e0);
  border-radius: var(--radii-sm, 0.25rem);
  background: var(--colors-background-control, #fcfcfc);
  color: var(--colors-text-default, #202020);
  font-family: var(--fonts-body, var(--font-inter, Inter)), sans-serif;
  font-size: 0.75rem;
  font-weight: 400;
  line-height: 1.125rem;
  outline: 0;
  transition: box-shadow 200ms cubic-bezier(0.2, 0.0, 0, 1.0), border-color 200ms cubic-bezier(0.2, 0.0, 0, 1.0);
}

.ds-input::placeholder {
  color: var(--colors-text-muted, #646464);
  opacity: 1;
}

.ds-input:focus {
  outline: 0;
  box-shadow: none;
}

.ds-input:focus-visible {
  outline-color: var(--sd-color-focus-ring, var(--colors-border-strong, #cecece));
}

.ds-input:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.ds-surface {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  padding: 0.5rem;
  border: 1px solid var(--colors-border-default, #e0e0e0);
  border-radius: var(--radii-lg, 0.5rem);
  background: var(--colors-background-surface, #f9f9f9);
  color: var(--colors-text-default, #202020);
  font-family: var(--fonts-body, var(--font-inter, Inter)), sans-serif;
}

.ds-surface strong {
  font-size: 0.875rem;
  font-weight: 600;
  line-height: 1.25rem;
}

.ds-surface p {
  margin: 0;
  color: var(--colors-text-muted, #646464);
  font-size: 0.875rem;
  line-height: 1.25;
}

.ds-navigation {
  display: flex;
  flex-direction: column;
  font-family: var(--fonts-body, var(--font-inter, Inter)), sans-serif;
}

.ds-navigation-link {
  display: flex;
  min-width: 0;
  gap: 0.25rem;
  padding: 0.25rem;
  border-radius: var(--radii-sm, 0.25rem);
  color: var(--colors-text-muted, #646464);
  text-decoration: none;
}

.ds-navigation-link:hover {
  background: var(--colors-control-hover-background);
  color: var(--colors-text-default, #202020);
}

.ds-navigation-link[aria-current="page"] {
  background: var(--colors-background-inset, #f0f0f0);
  color: var(--colors-text-default, #202020);
}

.ds-navigation-link:focus-visible {
  outline: 2px solid var(--colors-border-strong, #cecece);
  outline-offset: 1px;
}

.ds-badge {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  height: 1.5rem;
  padding: 0 0.625rem;
  border: 1px solid var(--colors-gray-6, #d9d9d9);
  border-radius: 9999px;
  background: var(--colors-gray-3, #f0f0f0);
  color: var(--colors-gray-text, #202020);
  font-family: var(--fonts-body, var(--font-inter, Inter)), sans-serif;
  font-size: 0.75rem;
  font-weight: 500;
  line-height: 1.125rem;
  white-space: nowrap;
}
